    if size(ptake,1) < 2
        ttake = "Info is not enough";
        ucost = NaN;
        return
    end

    % Calculate unit cost
    % Take all rows except the last (total cost column)
    quantities = ptake(:,1:end-1);
    total_costs = ptake(:,end);

    ucost = sum(quantities) ./ sum(total_costs);

    % Calculate total cost for future months
